python - <<'PY'
from PIL import Image
import numpy as np, heapq, math
im=np.asarray(Image.open('/app/target.png').convert('RGB'));mask=im.mean(2)<100
sk=np.asarray(Image.open('/app/output/target_skeleton.png').convert('L'))>0

def nearest(x,y):
 ys,xs=np.where(sk[y-3:y+4,x-3:x+4]);
 if not len(xs):raise ValueError()
 xs+=x-3;ys+=y-3;k=np.argmin((xs-x)**2+(ys-y)**2);return int(xs[k]),int(ys[k])
def path(a,b):
 a=nearest(*a);b=nearest(*b);steps=[(dx,dy,math.sqrt(dx*dx+dy*dy)) for dy in [-1,0,1] for dx in [-1,0,1] if dx or dy]
 q=[(0,a)];D={a:0};P={}
 while q:
  d,p=heapq.heappop(q)
  if d!=D[p]:continue
  if p==b:break
  x,y=p
  for dx,dy,c in steps:
   n=(x+dx,y+dy)
   if 0<=n[0]<1024 and 0<=n[1]<1024 and sk[n[1],n[0]] and d+c<D.get(n,1e9):D[n]=d+c;P[n]=p;heapq.heappush(q,(d+c,n))
 out=[b]
 while out[-1]!=a:out.append(P[out[-1]])
 return np.array(out[::-1],float)
strokes=[('s1',(287,344),(725,319)),('s2',(399,259),(442,397)),('s3',(587,238),(543,406)),('s4',(410,433),(237,659)),('s5',(370,549),(388,765)),('s6',(683,470),(447,666)),('s7',(528,442),(764,621))]
for nm,a,b in strokes:
 p=path(a,b); widths=[]
 for i,(x,y) in enumerate(p[5:-5],5):
  dx=p[i+5,0]-p[i-5,0];dy=p[i+5,1]-p[i-5,1];n=np.array([-dy,dx]);n=n/(np.linalg.norm(n)+1e-9)
  vals=[]
  for sign in [-1,1]:
   last=0
   for dist in np.arange(.5,80,.5):
    xx=int(round(x+sign*dist*n[0]));yy=int(round(y+sign*dist*n[1]))
    if xx<0 or xx>=1024 or yy<0 or yy>=1024 or not mask[yy,xx]:break
    last=dist
   vals.append(last)
  widths.append((vals[0]+vals[1]+1)*.22186)
 w=np.array(widths);good=w[w<np.percentile(w,90)]
 print(nm,'mean',round(float(good.mean()),1),'med',round(float(np.median(good)),1),'p10/p90',np.round(np.percentile(good,[10,50,90]),1).tolist(),'n',len(good))
 print(' profile every ~20%:',[(round(100*i/(len(w)-1)),round(float(w[i]),1)) for i in np.linspace(0,len(w)-1,6,dtype=int)])
